function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function validState(state) {
  if (!isRecord(state) || !isRecord(state.stock) || !Array.isArray(state.done)) return false;
  return Object.values(state.stock).every(value => Number.isInteger(value) && value >= 0);
}

function hasPermission(actor, from, to) {
  if (!isRecord(actor) || actor.role !== 'manager' || !Array.isArray(actor.stores)) return false;
  return actor.stores.includes(from) && actor.stores.includes(to);
}

function requestError(request, stock) {
  if (!isRecord(request)) return 'Invalid request';
  const { id, from, to, units, actor } = request;
  if (typeof id !== 'string' || id.trim().length === 0) return 'Invalid request id';
  if (!Number.isInteger(units) || units <= 0) return 'Invalid units';
  if (typeof from !== 'string' || typeof to !== 'string' || from === to) return 'Invalid stores';
  if (!Object.hasOwn(stock, from) || !Object.hasOwn(stock, to)) return 'Unknown store';
  if (!hasPermission(actor, from, to)) return 'Forbidden';
  return null;
}

function run({ state, request } = {}) {
  const fail = error => ({ state, ok: false, error });
  if (!validState(state)) return fail('Invalid state');
  const error = requestError(request, state.stock);
  if (error) return fail(error);
  if (state.done.includes(request.id)) return { state, ok: true };
  const { from, to, units, id } = request;
  if (state.stock[from] < units) return fail('Insufficient stock');
  const stock = {
    ...state.stock,
    [from]: state.stock[from] - units,
    [to]: state.stock[to] + units,
  };
  return { state: { ...state, stock, done: [...state.done, id] }, ok: true };
}

module.exports = { run };
